// The kit's stylesheet is hand-written CSS, not something the bundler produces, so it is
// placed next to the built JavaScript and announced in the exports map.
//
// The map is regenerated by tsdown from the JavaScript entry points, which is why this runs
// afterwards and adds the one entry tsdown has no way to know about. Consumers then write
// `import '@pg/ui/styles.css'`, and inside this repo the same specifier resolves to source.

import { copyFile, mkdir, readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

const at = (path) => fileURLToPath(new URL(`../packages/ui/${path}`, import.meta.url))

await mkdir(at('dist'), { recursive: true })
await copyFile(at('src/styles.css'), at('dist/styles.css'))

const manifestPath = at('package.json')
const manifest = JSON.parse(await readFile(manifestPath, 'utf8'))

const withStyles = (exports, target) => {
  const next = {}
  for (const [specifier, value] of Object.entries(exports)) {
    // Kept before `./package.json`, which conventionally goes last.
    if (specifier === './package.json') next['./styles.css'] = target
    next[specifier] = value
  }
  return next
}

manifest.exports = withStyles(manifest.exports, {
  '@pg/source': './src/styles.css',
  default: './dist/styles.css',
})

if (manifest.publishConfig?.exports) {
  manifest.publishConfig.exports = withStyles(manifest.publishConfig.exports, './dist/styles.css')
}

await writeFile(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`)

console.log('@pg/ui: styles.css copied to dist and added to the exports map')
